cssSegments.bc21abde2658281e:
.home-lint-range {
  bottom: 0;
  left: calc((var(--column) - 1) * 1ch);
  width: calc((var(--end) - var(--column)) * 1ch);
  border-inline: 1px solid var(--home-lint-tone);
  visibility: hidden;
  opacity: 0;
  height: .5rem;
  transition: opacity var(--home-base) var(--home-ease);
  position: absolute;

  &:before {
    background-color: var(--home-lint-tone);
    transform-origin: 0;
    content: "";
    height: 1px;
    position: absolute;
    top: 50%;
    left: 0;
    right: 0;
  }

  &:after, & > .home-lint-range-end {
    width: 1px;
    height: calc(var(--home-lint-lead) + (var(--line) - 1) * var(--home-lint-row) + .1875rem);
    background-image: linear-gradient(var(--home-lint-tone) 50%, transparent 50%);
    opacity: .7;
    transform-origin: top;
    content: "";
    background-size: 1px 3px;
    position: absolute;
    top: 100%;
    left: -1px;
  }

  & > .home-lint-range-end {
    left: auto;
    right: -1px;
  }

  .home-lint[data-phase="report"] & {
    visibility: visible;
    opacity: 1;

    &:before {
      animation-name: home-lint-draw;
      animation-duration: .6s;
      animation-timing-function: var(--home-ease);
      animation-delay: .1s;
      animation-fill-mode: both;
    }

    &:after, & > .home-lint-range-end {
      animation-name: home-lint-drop;
      animation-duration: .4s;
      animation-timing-function: var(--home-ease);
      animation-fill-mode: both;
    }

    & > .home-lint-range-end {
      animation-delay: .5s;
    }
  }
}

