cssSegments.ff59f165f4f0b780:
.home-hero-actions {
  justify-content: center;
  align-items: stretch;
  gap: var(--spacing-sm);
  min-width: 0;
  max-width: 100%;
  margin-top: var(--spacing-2xl);
  flex-wrap: wrap;
  display: flex;

  & .home-action-primary, & .home-command {
    box-sizing: border-box;
    min-width: 0;
    height: auto;
    min-height: 3.25rem;
    color: var(--home-text);
    border-radius: 1.625rem;
  }

  & .home-action-primary {
    isolation: isolate;
    padding: var(--spacing-sm) 1.5rem;
    font-weight: var(--font-weight-medium);
    color: var(--stone-text);
    text-shadow: 0 -1px light-dark(#00000080, #ffffffb3);
    background-color: var(--stone-mid);
    background-image: radial-gradient(ellipse 13% 18% at clamp(14%, var(--lit-x), 86%) 24%, color-mix(in oklab, var(--stone-glare) calc(var(--lit-near) * 100%), transparent), color-mix(in oklab, var(--stone-glare) calc(var(--lit-near) * 30%), transparent) 45%, transparent),
      radial-gradient(ellipse 80% 70% at var(--lit-x) -10%, var(--stone-sheen), transparent 70%),
      radial-gradient(ellipse 34% 70% at clamp(30%, calc(100% - var(--lit-x) * .5), 70%) 75%, var(--stone-adularescence), transparent),
      linear-gradient(180deg, var(--stone-top), var(--stone-mid) 52%, var(--stone-bottom));
    box-shadow: inset 0 1px 0 var(--stone-lip),
      inset 0 -1px 0 var(--stone-mirror),
      inset 0 -10px 16px -12px var(--stone-mirror),
      0 1px 1px var(--stone-contact),
      var(--cast-x) var(--cast-y) 10px -3px var(--stone-cast),
      calc(var(--cast-x) * 2.5) calc(var(--cast-y) * 2.5) 28px -10px var(--stone-cast);
    backdrop-filter: none;
    transition: background-color var(--home-quick) var(--home-ease);
    border: 0;
    position: relative;
    overflow: hidden;

    &:before {
      z-index: -1;
      border-radius: inherit;
      background-image: linear-gradient(var(--lit-angle), var(--stone-mirror), transparent 40%, transparent 58%, var(--stone-rim));
      pointer-events: none;
      content: "";
      padding: 1px;
      position: absolute;
      inset: 0;
      mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
    }

    &:after {
      z-index: -1;
      border-radius: inherit;
      background-image: linear-gradient(105deg, transparent 38%, var(--stone-glint) 50%, transparent 62%);
      pointer-events: none;
      content: "";
      background-position: 100% 0;
      background-repeat: no-repeat;
      background-size: 250% 100%;
      position: absolute;
      inset: 0;
    }

    &:is(:hover, :focus-visible) {
      --stone-adularescence: light-dark(#0000, oklch(90% .035 240 / .45));
      box-shadow: inset 0 1px 0 var(--stone-lip),
        inset 0 -1px 0 var(--stone-mirror),
        inset 0 -14px 20px -12px var(--stone-mirror),
        0 1px 1px var(--stone-contact),
        var(--cast-x) var(--cast-y) 12px -3px var(--stone-cast),
        calc(var(--cast-x) * 3) calc(var(--cast-y) * 3) 34px -10px var(--stone-cast);
      border-color: #0000;

      &:after {
        transition: background-position .9s var(--home-ease);
        background-position: 0 0;
      }
    }

    &:active {
      box-shadow: inset 0 2px 6px var(--stone-press),
        inset 0 -1px 0 var(--stone-mirror),
        0 1px 1px var(--stone-contact),
        calc(var(--cast-x) * .4) calc(var(--cast-y) * .4) 6px -3px var(--stone-cast);
    }
  }

  & .home-command {
    flex: auto;
    padding: .1875rem .1875rem .1875rem 1.125rem;
    font-size: .875rem;
  }

  & .home-command-copy {
    width: 2.75rem;
    height: 2.75rem;
    color: var(--home-text);
    border-radius: 3.40282e38px;

    &:hover {
      color: var(--home-text);
      background-color: light-dark(#00000009, #ffffff12);
    }

    &:focus-visible {
      outline-offset: -2px;
    }
  }

  & .home-action-primary:focus-visible {
    outline: 2px solid var(--home-ink);
    outline-offset: 4px;
  }

  @media (width < 40rem) {
    flex-direction: column;
    width: min(100%, 21rem);

    & .home-command {
      width: 100%;
    }
  }
}

